/* ============================================
   THREAD HISTORY
   A chat's history: labelled groups of thread rows (a status dot, the
   title and an optional description, a trailing icon, pin and meta, a
   hover-revealed menu, an inline rename) and a quiet row that reveals
   more. ThreadPanel seats it in its rail, and an AppSidebar section seats
   it through `content`, so both draw the same rows. The rows are the
   rails' shared 40px pill shape, AppSidebar's; the group heading is its
   category's face.
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

/* The icon line inside a row's pill: where the host rail's own row icons
   start, so the history's headings sit on that line and its dots and
   titles a glyph's bearing inside it. A rail hands its own through
   --ds-rail-icon-inset (AppSidebar's rows sit 16px in, in panel mode);
   ThreadPanel's rows, and the history alone, sit 8px in. */
.ds-thread-history {
  --ds-thread-history-icon-inset: var(--ds-rail-icon-inset, var(--padding-200));
  display: flex;
  flex-direction: column;
  gap: var(--gap-400);
  min-width: 0;
}

.ds-thread-history__group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
}

/* The rails' one group heading, AppSidebar's category and SubNavPanel's
   group label: paragraph small in the tertiary text, mixed case. Its
   20px line is the overline's it replaced, so the rhythm below is
   unchanged. On the rail's leading line, the logo's. The vertical padding
   is the rows' own inset restated — as if the label sat inside a row —
   so the heading keeps the pills' rhythm instead of hugging the
   new-thread row above and the first thread below. */
.ds-thread-history__group-label {
  padding: var(--padding-200);
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
}

.ds-thread-history__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  /* A hairline of air between fills, so stacked hover and active pills
     never read as one slab. */
  gap: 1px;
}

/* Thread rows keep the shared 40px shape — no height override, so they
   match the new-thread and control rows exactly. The <li> is the row's
   frame: relative, so the overflow trigger can sit over the trailing
   edge without living inside the row button (nested controls are
   invalid markup). */

.ds-thread-history__row {
  position: relative;
  min-width: 0;
}

.ds-thread-history__thread {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  width: 100%;
  height: 40px;
  min-width: 0;
  padding: var(--padding-200);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  cursor: pointer;
  overflow: hidden;
  text-align: start;
  text-decoration: none;
  transition: background-color var(--motion-duration-fast)
    var(--motion-ease-standard);
}

/* One seat in both states: the 20px inset (12 + 8) the collapsed circle's
   math needs is also where the expanded panel's marks sit, so no mark
   shifts as the rail sweeps. Text-led content sits a bearing deeper — see
   TEXT SEAT at the end of the file. */

.ds-thread-history__thread:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-thread-history__thread:focus-visible,
.ds-thread-history__more:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-thread-history__thread--active {
  background-color: var(--color-action-passive-bg-active);
}

/* A row with a description wraps to two lines: the title line keeps the
   shared height's rhythm, the description takes the full second line, and
   the row's gap becomes column-only so the lines sit close. */
.ds-thread-history__thread--detailed {
  height: auto;
  min-height: 40px;
  flex-wrap: wrap;
  column-gap: var(--gap-200);
  row-gap: 0;
}

/* The status dot: a StatusDot at its 8px list-row size leading the title.
   The panel seats one on every row or on none, so titles share an edge. */
.ds-thread-history__status {
  flex: none;
}

.ds-thread-history__title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  /* A long title dissolves at the trailing edge instead of clipping to an
     ellipsis — the fade is where the overflow trigger lands, so revealed
     text and control never fight. Short titles end before the fade zone
     and are untouched; the full text stays in the row's tooltip.
     ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
  mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
}

/* The trailing edge is the left in a right-to-left page. */
.ds-thread-history__title:dir(rtl) {
  /* ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(to left, black calc(100% - var(--gap-1000)), transparent);
  mask-image: linear-gradient(to left, black calc(100% - var(--gap-1000)), transparent);
}

/* The naming state: a shimmer bar holds the title's place while the host
   generates a name (Skeleton's sweep restated on the row's own geometry);
   the row's accessible name stays on its tooltip. */
.ds-thread-history__title--pending {
  display: flex;
  align-items: center;
}

.ds-thread-history__title-shimmer {
  display: block;
  /* Full width of the title's space — the row's inline padding is the
     only inset; the title mask softens its trailing end. */
  width: 100%;
  height: 0.75em;
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-secondary);
  position: relative;
  overflow: hidden;
}

.ds-thread-history__title-shimmer::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-bg-container-primary) 50%,
    transparent 100%
  );
  /* ds-allow(motion): Skeleton's shimmer — the sweep needs a symmetric
     in-out curve no --motion-ease-* token provides; the duration is
     tokenized. */
  animation: ds-thread-history-shimmer var(--motion-duration-loop-shimmer)
    ease-in-out infinite;
}

@keyframes ds-thread-history-shimmer {
  0% {
    transform: translateX(calc(-100% * var(--ds-inline-sign, 1)));
  }
  100% {
    transform: translateX(calc(100% * var(--ds-inline-sign, 1)));
  }
}

/* The description line: the caption face on the full second line, fading
   at the trailing edge like the title above it. Indented past the status
   dot's column, when the panel has one, so both lines share a left edge.
   ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
.ds-thread-history__description {
  flex-basis: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  -webkit-mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
  mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
}

/* The trailing edge is the left in a right-to-left page. */
.ds-thread-history__description:dir(rtl) {
  /* ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(to left, black calc(100% - var(--gap-1000)), transparent);
  mask-image: linear-gradient(to left, black calc(100% - var(--gap-1000)), transparent);
}

.ds-thread-history--dotted .ds-thread-history__description {
  /* The dot's width plus the row's column gap. */
  margin-inline-start: calc(var(--gap-200) + var(--gap-200));
}

/* The trailing cluster: session glyph, pin marker, and the meta caption,
   fading together when the overflow trigger needs their edge. */
.ds-thread-history__trail {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--gap-100);
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-history__thread-icon,
.ds-thread-history__pin {
  --icon-size: var(--icon-size-500);
  flex: none;
  color: var(--color-icon-secondary);
}

.ds-thread-history__meta {
  flex: none;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

/* ============================================
   THREAD MENU — the hover-revealed overflow trigger
   A 28px circular trigger over the row's faded trailing edge, opening the
   compact DropdownMenu. Hidden until the row is hovered or holds keyboard
   focus, and held while its menu is open — never standing on a resting
   row. The meta caption steps aside as the trigger arrives, since they
   share the trailing edge.
   ============================================ */

.ds-thread-history__row .ds-thread-history__menu {
  position: absolute;
  top: var(--padding-150);
  inset-inline-end: var(--padding-150);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-history__row:hover .ds-thread-history__menu,
.ds-thread-history__row:focus-within .ds-thread-history__menu,
.ds-thread-history__row .ds-thread-history__menu:has([aria-expanded='true']) {
  opacity: 1;
  pointer-events: auto;
}

.ds-thread-history__row--with-menu:hover .ds-thread-history__trail,
.ds-thread-history__row--with-menu:focus-within .ds-thread-history__trail,
.ds-thread-history__row--with-menu:has([aria-expanded='true'])
  .ds-thread-history__trail {
  opacity: 0;
}

/* While the menu is open the pointer is off in the panel, so the row holds
   its hover wash — the open menu and its row read as one thing. */
.ds-thread-history__row:has(.ds-thread-history__menu [aria-expanded='true'])
  .ds-thread-history__thread {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-thread-history__menu-trigger {
  --icon-size: var(--icon-size-500);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast)
    var(--motion-ease-standard);
}

.ds-thread-history__menu-trigger:hover {
  background-color: var(--color-bg-container-tertiary);
}

.ds-thread-history__menu-trigger:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

/* ============================================
   RENAME — the inline title editor
   The input wears the row's exact shape and face; the action-colour border is the
   active-input treatment, the one sanctioned "you are editing here" mark.
   ============================================ */

.ds-thread-history__rename {
  box-sizing: border-box;
  width: 100%;
  height: 40px;
  min-width: 0;
  padding: 0 var(--padding-200);
  border: var(--border-025) solid var(--color-action-primary-bg);
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-primary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  outline: none;
}

/* ============================================
   MORE — the quiet trailing reveal
   ============================================ */

.ds-thread-history__more {
  align-self: flex-start;
  padding: var(--padding-150) var(--padding-200);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  cursor: pointer;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  transition: color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-history__more:hover {
  color: var(--color-text-secondary);
}


/* ============================================
   FOLDING SECTIONS — `collapsibleSections`
   A heading stays a plain label on its seat; its fold is the chevron
   alone, a 24px icon button at the heading's end with a hover circle,
   named by the heading. The rows glide shut beneath it on SideNav's
   grid-rows fold.
   ============================================ */

.ds-thread-history__section-head {
  display: flex;
  align-items: center;
  min-width: 0;
}

.ds-thread-history__section-head > :first-child {
  flex: 1;
  min-width: 0;
}

.ds-thread-history__fold {
  --icon-size: var(--icon-size-500);
  margin-inline-end: var(--padding-200);
  display: inline-grid;
  place-items: center;
  flex: none;
  width: 24px;
  height: 24px;
  /* Taller than the heading's line by a step each side, given back so a
     foldable heading sits where a plain one does. */
  margin-block: calc(-1 * var(--gap-050));
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-icon-secondary);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard), color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-history__fold:hover {
  background-color: var(--color-action-passive-bg-hover);
  color: var(--color-icon-primary);
}

.ds-thread-history__fold:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

.ds-thread-history__fold-chevron {
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-thread-history__fold[aria-expanded='false'] .ds-thread-history__fold-chevron {
  transform: rotate(calc(-90deg * var(--ds-inline-sign, 1)));
}

.ds-thread-history__section-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-thread-history__section-panel--open {
  grid-template-rows: 1fr;
}

.ds-thread-history__section-panel > .ds-thread-history__list {
  min-height: 0;
}

/* The glide needs the rows clipped to the panel; a panel that never folds
   keeps them unclipped. */
.ds-thread-history--collapsible-sections .ds-thread-history__section-panel > .ds-thread-history__list {
  overflow: hidden;
}

/* ============================================
   TEXT SEAT — last, so it wins over each rule's padding shorthand
   ============================================ */

/* Text-led content — group labels, thread rows, the more row, the rename
   field — sits a bearing deeper than the icon seat: a glyph's ink starts
   that far inside its 24px box, so this is what lands the labels and status
   dots under the pen's visible edge while the glyph itself stays centred
   under the logo. None of it shows collapsed, so nothing moves. */
.ds-thread-history__thread,
.ds-thread-history__more,
.ds-thread-history__rename {
  padding-inline-start: calc(var(--ds-thread-history-icon-inset) + var(--padding-100));
}

/* Group headings sit on the rail's leading line, the logo's and the row
   icons', where AppSidebar's category does. */
.ds-thread-history__group-label {
  padding-inline-start: var(--ds-thread-history-icon-inset);
}

/* A row's trailing item (the meta caption) keeps AppSidebar's badge room
   from its pill's end, a step more than the pill's own inset. */
.ds-thread-history__thread {
  padding-inline-end: var(--padding-300);
}

/* Icon side padding, Button's rule (design.md): a glyph's box carries its
   own side bearing, so a side that holds one takes the step below the text
   side. A thread row that shows its icon leads with it, so it starts
   on the icon rows' line rather than the text rows' (12 → 8). */
.ds-thread-history__thread:has(.ds-thread-history__thread-icon) {
  padding-inline-start: var(--ds-thread-history-icon-inset);
}

/* A host that seats the history on a touch surface (a phone drawer) keeps
   the row menu showing, since there is no hover to reveal it. */
@media (hover: none) {
  .ds-thread-history__row .ds-thread-history__menu {
    opacity: 1;
    pointer-events: auto;
  }

  .ds-thread-history__row--with-menu .ds-thread-history__trail {
    opacity: 0;
  }
}

} /* @layer rift.components */

import React from 'react';
import type { LinkComponent } from '../../behaviors/LinkProvider';
import { DropdownMenu } from '../DropdownMenu/DropdownMenu';
import { StatusDot } from '../StatusDot/StatusDot';
import type { StatusDotProps } from '../StatusDot/StatusDot';
import type {
  ThreadPanelGroup,
  ThreadPanelThreadAction,
  ThreadPanelThreadStatus,
} from '../ThreadPanel/ThreadPanel';
import './ThreadHistory.css';
import '../../behaviors/direction.css';
import '../../behaviors/visually-hidden.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';

/** Props owned by ThreadHistory itself — everything else falls through to the root `<nav>`. */
type ThreadHistoryOwnProps = {
  /** The history, in display order. A flat list is one group with no label. Each thread takes ThreadPanel's thread shape. */
  groups: ThreadPanelGroup[];
  /** Id of the thread on stage. Its row renders filled and carries `aria-current`. */
  activeThreadId?: string;
  /** Fires with the clicked thread's id. Rows with an `href` navigate as well. */
  onThreadSelect?: (id: string) => void;
  /** Shared menu actions for every thread row, behind a hover-revealed trailing trigger (always shown on a touch screen); a thread's own `actions` overrides the set. The menu renders only when `onThreadAction` is also given, and never on a `pending` row. */
  threadActions?: ThreadPanelThreadAction[];
  /** Fires with the thread's id and the chosen action's id. */
  onThreadAction?: (threadId: string, actionId: string) => void;
  /** Spoken text for each thread status, read after the row's title; the dot itself is decorative. Merged over the English defaults (Working, Unread, Needs input, Failed). `idle` is silent unless given a label here. */
  statusLabels?: Partial<Record<ThreadPanelThreadStatus, string>>;
  /** Spoken text for a `pinned` thread, read after the title and any status; the pin glyph itself is decorative. */
  pinnedLabel?: string;
  /**
   * Accessible name for a row's menu trigger. A string is followed by a colon
   * and the thread's title ("Thread options: Q3 plan"); a function is given
   * the title and returns the whole name, so a translation can put the title
   * where its grammar needs it.
   */
  threadMenuLabel?: string | ((title: string) => string);
  /** Id of the thread being renamed: its row swaps to an inline text field, prefilled with the title and selected. The host owns the state. */
  renamingThreadId?: string;
  /** Fires with the thread's id and the trimmed new title when a rename commits (Enter, or focus leaving the field). An empty or unchanged value fires `onRenameCancel` instead. */
  onThreadRename?: (threadId: string, title: string) => void;
  /** Fires when a rename ends without a change: Escape, an empty value, or an unchanged title. */
  onRenameCancel?: () => void;
  /** Accessible name for the inline rename field. */
  renameLabel?: string;
  /** Text for the quiet trailing row that reveals older threads, e.g. "Show 20 more". Renders only when given. */
  moreLabel?: string;
  /** Fires when the more row is clicked. */
  onShowMore?: () => void;
  /**
   * Let the reader fold each labelled group under its heading: the heading
   * becomes a toggle with a chevron, and the rows glide shut beneath it.
   * @default false
   */
  collapsibleSections?: boolean;
  /** The folded groups, by label. Controlled: pair it with `onCollapsedSectionsChange`. Needs `collapsibleSections`. */
  collapsedSections?: string[];
  /** Fires with the full new list of folded groups when a heading is pressed. */
  onCollapsedSectionsChange?: (collapsedSections: string[]) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * The component its links render with, such as Next.js's `Link`, so they
   * navigate through the app's router; a plain `<a>` when unset. This
   * component can render on the server, so it never reads a LinkProvider:
   * pass the prop even under one.
   */
  linkComponent?: LinkComponent;
};

export interface ThreadHistoryProps
  extends ThreadHistoryOwnProps,
    Omit<React.ComponentPropsWithRef<'nav'>, keyof ThreadHistoryOwnProps> {}

const baseClass = 'ds-thread-history';

/** How each thread status draws its StatusDot: fill for "wants you",
    colour for what it wants, the pulse for live. */
const STATUS_DOTS: Record<
  ThreadPanelThreadStatus,
  Pick<StatusDotProps, 'variant' | 'outline' | 'pulse'>
> = {
  idle: { variant: 'neutral', outline: true },
  working: { variant: 'neutral', pulse: true },
  unread: { variant: 'info' },
  waiting: { variant: 'warning' },
  error: { variant: 'error' },
};

const DEFAULT_STATUS_LABELS: Partial<Record<ThreadPanelThreadStatus, string>> =
  {
    working: 'Working',
    unread: 'Unread',
    waiting: 'Needs input',
    error: 'Failed',
  };

/** A row that is a `<button>`, or an `<a>` when an href is supplied (Button's pattern). */
function ActionRow({
  className,
  href,
  onClick,
  ariaCurrent,
  title,
  children,
  link: Link,
}: {
  className: string;
  href?: string;
  onClick?: () => void;
  ariaCurrent?: 'page' | 'true';
  title?: string;
  children: React.ReactNode;
  link: LinkComponent;
}) {
  if (href) {
    return (
      <Link
        className={className}
        href={href}
        onClick={onClick}
        aria-current={ariaCurrent === 'true' ? 'page' : ariaCurrent}
        title={title}
      >
        {children}
      </Link>
    );
  }
  return (
    <button
      type="button"
      className={className}
      onClick={onClick}
      aria-current={ariaCurrent}
      title={title}
    >
      {children}
    </button>
  );
}

/** The inline rename field. Uncontrolled: Enter commits, Escape cancels,
    and focus leaving the field commits too — an empty or unchanged value
    cancels instead, since half a title is not a title. The keyboard paths
    hand focus back to the row once the host swaps it in; a blur commit
    leaves focus where the user sent it. Hook-free on purpose, so the
    module stays renderable from a Server Component (the field itself only
    renders when the host wires the rename callbacks, which already means
    a client host). */
function RenameField({
  baseClass,
  defaultValue,
  label,
  onSubmit,
  onCancel,
}: {
  baseClass: string;
  defaultValue: string;
  label: string;
  onSubmit: (value: string) => void;
  onCancel?: () => void;
}) {
  const commit = (el: HTMLInputElement) => {
    const value = el.value.trim();
    if (value && value !== defaultValue) onSubmit(value);
    else onCancel?.();
  };
  /* The row's button mounts only after the host clears the rename state,
     so the hand-back polls a few frames for the swap to land — one frame
     is a race against the host's re-render. */
  const refocusRow = (el: HTMLInputElement) => {
    const row = el.closest('li');
    const tryFocus = (attempt: number) => {
      const target = row?.querySelector<HTMLElement>('button, a');
      if (target) target.focus();
      else if (attempt < 3) requestAnimationFrame(() => tryFocus(attempt + 1));
    };
    requestAnimationFrame(() => tryFocus(0));
  };
  return (
    <input
      className={`${baseClass}__rename`}
      type="text"
      defaultValue={defaultValue}
      aria-label={label}
      ref={(el) => {
        /* Focus and select once on mount; the activeElement guard keeps a
           parent re-render from re-selecting mid-typing. */
        if (el && document.activeElement !== el) {
          el.focus();
          el.select();
        }
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          e.stopPropagation();
          refocusRow(e.currentTarget);
          commit(e.currentTarget);
        } else if (e.key === 'Escape') {
          /* Stop here so a host dialog (the chat sheet) doesn't close on
             the same keystroke. */
          e.stopPropagation();
          refocusRow(e.currentTarget);
          onCancel?.();
        }
      }}
      onBlur={(e) => commit(e.currentTarget)}
    />
  );
}

/**
 * ThreadHistory is a chat's thread history: labelled groups of thread rows
 * and an optional row that reveals more. ThreadPanel seats it in its rail,
 * and an AppSidebar section seats it through `content`, so a chat built on
 * the app rail draws the same rows. A row scales from a bare title to the
 * full anatomy: a leading status dot (all rows or none, so titles share an
 * edge), a quiet description line, a trailing glyph, a pin marker and the
 * meta caption, a hover-revealed overflow menu (always shown on a touch
 * screen), a shimmer while a `pending` thread is named, and an inline
 * rename field.
 *
 * Fully controlled and stateless: the host owns the active thread, the
 * rename state and the folded groups. Carries no `'use client'` directive,
 * so rendered with links alone it works from a React Server Component; the
 * menu and the rename take callbacks, so they belong to client hosts.
 *
 * The root is a `<nav>` named "Thread history" by default; pass
 * `aria-label` to name it differently. The ref and unrecognised props
 * reach it.
 */
export function ThreadHistory({
  groups,
  activeThreadId,
  onThreadSelect,
  threadActions,
  onThreadAction,
  statusLabels,
  pinnedLabel = 'Pinned',
  threadMenuLabel = 'Thread options',
  renamingThreadId,
  onThreadRename,
  onRenameCancel,
  renameLabel = 'Rename thread',
  moreLabel,
  onShowMore,
  collapsibleSections = false,
  collapsedSections = [],
  onCollapsedSectionsChange,
  className = '',
  linkComponent,
  ref,
  ...rest
}: ThreadHistoryProps) {
  /* The dot column is all or nothing: one thread with a status seats a
     dot on every row, so the titles keep a shared left edge. */
  const dotted = groups.some((group) =>
    group.threads.some((thread) => thread.status || thread.unread),
  );
  const labels = { ...DEFAULT_STATUS_LABELS, ...statusLabels };
  const Link = linkComponent ?? 'a';
  const iconClass = 'material-symbols-rounded';
    /* Groups fold only when asked, under their headings. */
    const folds = collapsibleSections;
    const isFolded = (heading: string) => folds && collapsedSections.includes(heading);
    const toggleSection = (heading: string) =>
      onCollapsedSectionsChange?.(
        collapsedSections.includes(heading)
          ? collapsedSections.filter((entry) => entry !== heading)
          : [...collapsedSections, heading],
      );
    /* A section's heading: the plain label, or with `collapsibleSections`
       the same label as a toggle with a chevron. */
    const heading = (text: string, className: string) => (
      <div className={`${baseClass}__section-head`}>
        <span className={className}>{text}</span>
        {/* The fold is the chevron alone, named by the heading's own text,
            so the heading keeps its seat on the icon line and only the
            chevron answers the pointer. */}
        {folds && (
          <button
            type="button"
            className={`${baseClass}__fold`}
            aria-label={text}
            aria-expanded={!isFolded(text)}
            onClick={() => toggleSection(text)}
          >
            <span className={`${iconClass} ${baseClass}__fold-chevron`} aria-hidden="true">
              expand_more
            </span>
          </button>
        )}
      </div>
    );
    /* The rows under a heading, in a panel that glides shut when it folds
       (SideNav's grid-rows fold); open, it adds nothing. */
    const panel = (text: string | undefined, list: React.ReactNode) => {
      const shut = Boolean(text && isFolded(text));
      return (
        <div
          className={`${baseClass}__section-panel${shut ? '' : ` ${baseClass}__section-panel--open`}`}
          inert={shut}
        >
          {list}
        </div>
      );
    };

  return (
    <nav
      aria-label="Thread history"
      {...rest}
      ref={ref}
      className={[baseClass, dotted && `${baseClass}--dotted`, collapsibleSections && `${baseClass}--collapsible-sections`, className]
        .filter(Boolean)
        .join(' ')}
    >
          {groups.map(
            (group, index) =>
              group.threads.length > 0 && (
                <div
                  key={group.label ?? index}
                  className={`${baseClass}__group`}
                >
                  {group.label && heading(group.label, `${baseClass}__group-label`)}
                  {panel(group.label, (
                  <ul
                    className={`${baseClass}__list`}
                    aria-label={group.label}
                  >
                    {group.threads.map((thread) => {
                      const active = thread.id === activeThreadId;
                      const actions = thread.actions ?? threadActions;
                      const showMenu = Boolean(
                        actions &&
                          actions.length > 0 &&
                          onThreadAction &&
                          !thread.pending,
                      );
                      /* A thread still being named is, by definition,
                         mid-run. */
                      const status: ThreadPanelThreadStatus | undefined =
                        dotted
                          ? thread.pending
                            ? 'working'
                            : (thread.status ??
                              (thread.unread ? 'unread' : 'idle'))
                          : undefined;
                      const statusLabel =
                        status && !thread.pending ? labels[status] : undefined;
                      const renaming = Boolean(
                        thread.id === renamingThreadId && onThreadRename,
                      );
                      return (
                        <li
                          key={thread.id}
                          className={[
                            `${baseClass}__row`,
                            showMenu && `${baseClass}__row--with-menu`,
                          ]
                            .filter(Boolean)
                            .join(' ')}
                        >
                          {renaming ? (
                            <RenameField
                              baseClass={baseClass}
                              defaultValue={thread.title}
                              label={renameLabel}
                              onSubmit={(value) =>
                                onThreadRename?.(thread.id, value)
                              }
                              onCancel={onRenameCancel}
                            />
                          ) : (
                            <>
                              <ActionRow
                                link={Link}
                                className={[
                                  `${baseClass}__thread`,
                                  active && `${baseClass}__thread--active`,
                                  thread.description &&
                                    !thread.pending &&
                                    `${baseClass}__thread--detailed`,
                                ]
                                  .filter(Boolean)
                                  .join(' ')}
                                href={thread.href}
                                onClick={
                                  onThreadSelect
                                    ? () => onThreadSelect(thread.id)
                                    : undefined
                                }
                                ariaCurrent={
                                  active
                                    ? thread.href
                                      ? 'page'
                                      : 'true'
                                    : undefined
                                }
                                title={thread.title}
                              >
                                {status && (
                                  <StatusDot
                                    className={`${baseClass}__status`}
                                    size="xs"
                                    decorative
                                    {...STATUS_DOTS[status]}
                                  />
                                )}
                                {thread.pending ? (
                                  /* The naming state: the shimmer holds the
                                     title's place; the row's accessible name
                                     comes from its tooltip. */
                                  <span
                                    className={`${baseClass}__title ${baseClass}__title--pending`}
                                  >
                                    <span
                                      className={`${baseClass}__title-shimmer`}
                                      aria-hidden="true"
                                    />
                                  </span>
                                ) : (
                                  <span className={`${baseClass}__title`}>
                                    {thread.title}
                                  </span>
                                )}
                                {statusLabel && (
                                  <span className="ds-visually-hidden">
                                    {statusLabel}
                                  </span>
                                )}
                                {/* The pin glyph below is decorative, so its
                                    meaning rides in the row's text, the
                                    status label's manner. */}
                                {thread.pinned && !thread.pending && (
                                  <span className="ds-visually-hidden">
                                    {pinnedLabel}
                                  </span>
                                )}
                                {!thread.pending &&
                                  (thread.icon ||
                                    thread.pinned ||
                                    thread.meta) && (
                                    <span className={`${baseClass}__trail`}>
                                      {thread.icon && (
                                        <span
                                          className={`${baseClass}__thread-icon${typeof thread.icon === 'string' ? ` ${iconClass} ${mirrorClass(thread.icon)}` : ''}`}
                                          aria-hidden="true"
                                        >
                                          {thread.icon}
                                        </span>
                                      )}
                                      {thread.pinned && (
                                        <span
                                          className={`${baseClass}__pin ${iconClass}`}
                                          aria-hidden="true"
                                        >
                                          keep
                                        </span>
                                      )}
                                      {thread.meta && (
                                        <span className={`${baseClass}__meta`}>
                                          {thread.meta}
                                        </span>
                                      )}
                                    </span>
                                  )}
                                {thread.description && !thread.pending && (
                                  <span
                                    className={`${baseClass}__description`}
                                  >
                                    {thread.description}
                                  </span>
                                )}
                              </ActionRow>
                              {showMenu && actions && (
                                <DropdownMenu
                                  className={`${baseClass}__menu`}
                                  align="end"
                                  size="compact"
                                  items={actions.map((action) => ({
                                    label: action.label,
                                    icon: action.icon,
                                    destructive: action.destructive,
                                    onClick: () =>
                                      onThreadAction?.(thread.id, action.id),
                                  }))}
                                  trigger={
                                    <button
                                      type="button"
                                      className={`${baseClass}__menu-trigger`}
                                      aria-label={
                                        typeof threadMenuLabel === 'function'
                                          ? threadMenuLabel(thread.title)
                                          : `${threadMenuLabel}: ${thread.title}`
                                      }
                                    >
                                      <span
                                        className={iconClass}
                                        aria-hidden="true"
                                      >
                                        more_horiz
                                      </span>
                                    </button>
                                  }
                                />
                              )}
                            </>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                  ))}
                </div>
              ),
          )}
          {moreLabel && (
            <button
              type="button"
              className={`${baseClass}__more`}
              onClick={onShowMore}
            >
              {moreLabel}
            </button>
          )}
    </nav>
  );
}
